"use strict";(Array.isArray(self.webpackChunkwoocommerce_multivendor_marketplace_docs)?self.webpackChunkwoocommerce_multivendor_marketplace_docs:self.webpackChunkwoocommerce_multivendor_marketplace_docs=[]).push([[6206],{40800(e,t,a){a.r(t),a.d(t,{comp:()=>p,data:()=>d});var r=a(20641);const o=a.p+"assets/img/marketplace-magic-ai-prompt-anatomy.7f1dad81.webp",n=a.p+"assets/img/marketplace-magic-ai-generated-output-review.96735afd.webp",i=a.p+"assets/img/marketplace-magic-ai-multimodal-vision-prompt.706d204b.webp",s=a.p+"assets/img/marketplace-magic-ai-image-enhancer-prompt.ca495e83.webp",l=a.p+"assets/img/marketplace-magic-ai-inline-field-prompt.dc1f8875.webp",c={},p=(0,a(66262).A)(c,[["render",function(e,t){return(0,r.uX)(),(0,r.CE)("div",null,t[0]||(t[0]=[(0,r.Fv)('<h1 id="prompt-customization-best-practices" tabindex="-1"><a class="header-anchor" href="#prompt-customization-best-practices"><span>Prompt Customization &amp; Best Practices</span></a></h1><p>Crafting clear, specific prompts helps <strong>Magic AI</strong> generate polished, accurate, and high-converting product listings. This guide provides recommended prompt structures, best practices, and copy templates for both store administrators and marketplace vendors.</p><div class="hint-container tip"><p class="hint-container-title">Golden Rule of AI Prompts</p><p>The more specific and descriptive your starting input (materials, dimensions, target audience, brand tone), the more complete and accurate the generated product listing will be.</p></div><hr><h2 id="the-anatomy-of-an-effective-product-prompt" tabindex="-1"><a class="header-anchor" href="#the-anatomy-of-an-effective-product-prompt"><span>The Anatomy of an Effective Product Prompt</span></a></h2><p>An ideal prompt covers four core elements:</p><table><thead><tr><th>Prompt Component</th><th>Key Information to Include</th><th>Practical Example</th></tr></thead><tbody><tr><td><strong>1. Core Product</strong></td><td>Product type, model, and form factor</td><td><em>&quot;AeroTune Pro wireless over-ear noise-cancelling headphones&quot;</em></td></tr><tr><td><strong>2. Materials &amp; Specs</strong></td><td>Dimensions, weight, technical specifications</td><td><em>&quot;40mm titanium drivers, Bluetooth 5.4, 45-hour battery life&quot;</em></td></tr><tr><td><strong>3. Target Audience</strong></td><td>Intended buyer persona and primary use cases</td><td><em>&quot;Remote professionals, frequent travelers, and daily commuters&quot;</em></td></tr><tr><td><strong>4. Tone &amp; Pricing</strong></td><td>Desired copy style and target pricing</td><td><em>&quot;Modern, premium, professional tone. Target price: $149&quot;</em></td></tr></tbody></table><p><a class="doc-image-link" href="./assets/marketplace-magic-ai-prompt-anatomy.webp"><img src="'+o+'" alt="Magic AI Prompt Formulation Interface with Core Specs and Target Fields"></a></p><hr><h2 id="high-converting-copy-templates" tabindex="-1"><a class="header-anchor" href="#high-converting-copy-templates"><span>High-Converting Copy Templates</span></a></h2><h3 id="_1-electronics-gadgets" tabindex="-1"><a class="header-anchor" href="#_1-electronics-gadgets"><span>1. Electronics &amp; Gadgets</span></a></h3><blockquote><p><strong>Prompt Example:</strong><br><em>&quot;Wireless over-ear noise-cancelling headphones, 40mm titanium drivers, Bluetooth 5.4, 45-hour battery life with USB-C fast charging (5 mins = 4 hours). Memory foam ear cushions, foldable travel design, built-in dual beamforming microphones for calls. Target audience: remote professionals and commuters. Target price: $149.&quot;</em></p></blockquote><p><strong>What Magic AI Produces:</strong></p><ul><li><strong>Product Name:</strong> <em>AeroTune Pro Wireless Noise-Cancelling Over-Ear Headphones (45H Battery, Bluetooth 5.4)</em></li><li><strong>Short Description:</strong> <em>Block out distractions and immerse yourself in premium acoustic sound with 40mm titanium drivers, active noise cancellation, and a plush memory-foam travel design.</em></li><li><strong>Long Description:</strong> Comprehensive breakdown of acoustic engineering, battery longevity benchmarks, call clarity, and in-the-box contents.</li></ul><p><a class="doc-image-link" href="./assets/marketplace-magic-ai-generated-output-review.webp"><img src="'+n+'" alt="Magic AI Review Screen Displaying Generated Product Fields and One-Click Application"></a></p><hr><h3 id="_2-apparel-fashion-accessories" tabindex="-1"><a class="header-anchor" href="#_2-apparel-fashion-accessories"><span>2. Apparel, Fashion &amp; Accessories</span></a></h3><blockquote><p><strong>Prompt Example:</strong><br><em>&quot;Women&#39;s oversized cable-knit turtleneck sweater, 100% organic merino wool, heavyweight 7-gauge knit, ribbed cuffs and hem, drop shoulders. Available in Oat Milk and Charcoal. Gentle hand wash only. Designed for cozy autumn and winter layering. Target price: $88.&quot;</em></p></blockquote><p><strong>What Magic AI Produces:</strong></p><ul><li><strong>Product Name:</strong> <em>Merino Wool Oversized Cable-Knit Turtleneck Sweater</em></li><li><strong>Short Description:</strong> <em>Stay effortlessly warm with pure organic merino wool, featuring an artisan cable-knit texture and relaxed drop-shoulder silhouette for chic cold-weather styling.</em></li><li><strong>Long Description:</strong> Fabric provenance details, styling tips (pairs with denim or skirts), sizing recommendations, and wool garment care instructions.</li></ul><hr><h3 id="_3-home-furniture-kitchenware" tabindex="-1"><a class="header-anchor" href="#_3-home-furniture-kitchenware"><span>3. Home, Furniture &amp; Kitchenware</span></a></h3><blockquote><p><strong>Prompt Example:</strong><br><em>&quot;Handcrafted ceramic pour-over coffee dripper with matching 500ml glass carafe. Matte speckled ivory glaze on stoneware, heat-resistant borosilicate glass, silicone base ring. Fits standard V-shaped size 02 paper filters. Dishwasher safe. Target price: $42.&quot;</em></p></blockquote><p><strong>What Magic AI Produces:</strong></p><ul><li><strong>Product Name:</strong> <em>Artisan Stoneware Pour-Over Coffee Maker Set with 500ml Borosilicate Carafe</em></li><li><strong>Short Description:</strong> <em>Brew cafe-quality pour-over coffee at home with handcrafted ceramic heat retention and an ergonomic heat-safe serving carafe.</em></li><li><strong>Long Description:</strong> Step-by-step brewing guide, extraction benefits of stoneware thermal mass, material safety specifications, and cleaning tips.</li></ul><hr><h2 id="multimodal-vision-prompts-using-reference-photos" tabindex="-1"><a class="header-anchor" href="#multimodal-vision-prompts-using-reference-photos"><span>Multimodal Vision Prompts (Using Reference Photos)</span></a></h2><p>When uploading reference photos of physical items, combine your image with a focused prompt:</p><ul><li><strong>State What the Photo Shows:</strong> <em>&quot;See attached 2 photos of our handcrafted leather messenger bag. Highlight the antique brass hardware, double-stitched corners, and laptop compartment shown in photo 2.&quot;</em></li><li><strong>Clarify Hidden Features:</strong> <em>&quot;The photo shows the exterior matte black finish; please note that the interior features waterproof nylon lining with 3 slip pockets.&quot;</em></li></ul><p><a class="doc-image-link" href="./assets/marketplace-magic-ai-multimodal-vision-prompt.webp"><img src="'+i+'" alt="Multimodal Vision AI Prompt with Reference Photo Attachments"></a></p><hr><h2 id="image-enhancer-prompt-templates" tabindex="-1"><a class="header-anchor" href="#image-enhancer-prompt-templates"><span>Image Enhancer Prompt Templates</span></a></h2><p>When using the <strong>Vendor Image Enhancer</strong> below the product thumbnail, use these proven styling prompts:</p><h3 id="_1-clean-studio-pure-white-amazon-marketplace-standard" tabindex="-1"><a class="header-anchor" href="#_1-clean-studio-pure-white-amazon-marketplace-standard"><span>1. Clean Studio &amp; Pure White (Amazon &amp; Marketplace Standard)</span></a></h3><blockquote><p><em>&quot;Remove the cluttered room background. Place the athletic training shirt on a seamless pure white studio surface with soft, diffused commercial lighting, smooth fabric drape, and subtle contact shadows underneath.&quot;</em></p></blockquote><h3 id="_2-modern-lifestyle-warm-interior" tabindex="-1"><a class="header-anchor" href="#_2-modern-lifestyle-warm-interior"><span>2. Modern Lifestyle &amp; Warm Interior</span></a></h3><blockquote><p><em>&quot;Keep the product completely unchanged, but place it naturally on a natural oak dining table in a sunlit Scandinavian apartment with gentle ambient daylight and blurred background greenery.&quot;</em></p></blockquote><h3 id="_3-luxury-moody-boutique" tabindex="-1"><a class="header-anchor" href="#_3-luxury-moody-boutique"><span>3. Luxury / Moody Boutique</span></a></h3><blockquote><p><em>&quot;Place the item on a dark reflective black granite surface with dramatic rim lighting, soft reflections, and subtle golden bokeh in the deep background.&quot;</em></p></blockquote><h3 id="_4-outdoor-adventure" tabindex="-1"><a class="header-anchor" href="#_4-outdoor-adventure"><span>4. Outdoor / Adventure</span></a></h3><blockquote><p><em>&quot;Place the hiking boot on a rugged granite mountain ledge with warm sunrise sunlight casting long soft shadows.&quot;</em></p></blockquote><p><a class="doc-image-link" href="./assets/marketplace-magic-ai-image-enhancer-prompt.webp"><img src="'+s+'" alt="Vendor Product Image Enhancer Interface with Clean Studio Styling Prompt"></a></p><hr><h2 id="prompt-engineering-do-s-don-ts" tabindex="-1"><a class="header-anchor" href="#prompt-engineering-do-s-don-ts"><span>Prompt Engineering Do&#39;s &amp; Don&#39;ts</span></a></h2><table><thead><tr><th>Do&#39;s</th><th>Don&#39;ts</th></tr></thead><tbody><tr><td><strong>Do:</strong> Include numerical specs (battery hours, dimensions, capacity).</td><td><strong>Don&#39;t:</strong> Avoid vague single-word prompts like &quot;shoe&quot; or &quot;phone&quot;.</td></tr><tr><td><strong>Do:</strong> Specify your target customer (students, athletes, luxury buyers).</td><td><strong>Don&#39;t:</strong> Don&#39;t ask the AI to guess technical standards without guidance.</td></tr><tr><td><strong>Do:</strong> Mention care and warranty details for richer descriptions.</td><td><strong>Don&#39;t:</strong> Avoid conflicting instructions (e.g., &quot;cheap but luxury&quot;).</td></tr><tr><td><strong>Do:</strong> Use single-field inline buttons to tweak specific sections quickly.</td><td><strong>Don&#39;t:</strong> Don&#39;t republish without reviewing pricing and stock numbers.</td></tr></tbody></table><p><a class="doc-image-link" href="./assets/marketplace-magic-ai-inline-field-prompt.webp"><img src="'+l+'" alt="Inline Single-Field AI Prompt Dialog for Quick Content Refinements"></a></p>',46)]))}]]),d=JSON.parse('{"path":"/documentation/ai-prompt-engineering.html","title":"Prompt Customization & Best Practices","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"The Anatomy of an Effective Product Prompt","slug":"the-anatomy-of-an-effective-product-prompt","link":"#the-anatomy-of-an-effective-product-prompt","children":[]},{"level":2,"title":"High-Converting Copy Templates","slug":"high-converting-copy-templates","link":"#high-converting-copy-templates","children":[{"level":3,"title":"1. Electronics & Gadgets","slug":"_1-electronics-gadgets","link":"#_1-electronics-gadgets","children":[]},{"level":3,"title":"2. Apparel, Fashion & Accessories","slug":"_2-apparel-fashion-accessories","link":"#_2-apparel-fashion-accessories","children":[]},{"level":3,"title":"3. Home, Furniture & Kitchenware","slug":"_3-home-furniture-kitchenware","link":"#_3-home-furniture-kitchenware","children":[]}]},{"level":2,"title":"Multimodal Vision Prompts (Using Reference Photos)","slug":"multimodal-vision-prompts-using-reference-photos","link":"#multimodal-vision-prompts-using-reference-photos","children":[]},{"level":2,"title":"Image Enhancer Prompt Templates","slug":"image-enhancer-prompt-templates","link":"#image-enhancer-prompt-templates","children":[{"level":3,"title":"1. Clean Studio & Pure White (Amazon & Marketplace Standard)","slug":"_1-clean-studio-pure-white-amazon-marketplace-standard","link":"#_1-clean-studio-pure-white-amazon-marketplace-standard","children":[]},{"level":3,"title":"2. Modern Lifestyle & Warm Interior","slug":"_2-modern-lifestyle-warm-interior","link":"#_2-modern-lifestyle-warm-interior","children":[]},{"level":3,"title":"3. Luxury / Moody Boutique","slug":"_3-luxury-moody-boutique","link":"#_3-luxury-moody-boutique","children":[]},{"level":3,"title":"4. Outdoor / Adventure","slug":"_4-outdoor-adventure","link":"#_4-outdoor-adventure","children":[]}]},{"level":2,"title":"Prompt Engineering Do\'s & Don\'ts","slug":"prompt-engineering-do-s-don-ts","link":"#prompt-engineering-do-s-don-ts","children":[]}],"git":{},"filePathRelative":"documentation/ai-prompt-engineering.md"}')}}]);